import AppKit

/// Watches the Mac pasteboard (there's no change notification API, so it polls changeCount — cheap).
final class ClipboardSync {
    private static let enabledKey = "syncClipboard"
    /// Password managers mark secrets with these; never send them to the phone.
    private static let skipTypes: Set<String> = [
        "org.nspasteboard.ConcealedType", "org.nspasteboard.TransientType", "org.nspasteboard.AutoGeneratedType",
    ]

    private let pb = NSPasteboard.general
    private var lastCount = NSPasteboard.general.changeCount
    private var timer: Timer?

    var onLocalText: ((String) -> Void)?

    var enabled: Bool {
        get { UserDefaults.standard.object(forKey: Self.enabledKey) as? Bool ?? true }
        set { UserDefaults.standard.set(newValue, forKey: Self.enabledKey) }
    }

    func start() {
        timer = Timer.scheduledTimer(withTimeInterval: 0.5, repeats: true) { [weak self] _ in self?.tick() }
    }

    private func tick() {
        guard pb.changeCount != lastCount else { return }
        lastCount = pb.changeCount
        guard enabled, let text = currentText() else { return }
        onLocalText?(text)
    }

    func currentText() -> String? {
        let types = Set((pb.types ?? []).map(\.rawValue))
        guard types.isDisjoint(with: Self.skipTypes),
              let s = pb.string(forType: .string), !s.isEmpty, s.utf8.count <= 1_000_000 else { return nil }
        return s
    }

    /// PNG of the current pasteboard image, if any.
    func currentImagePNG() -> Data? {
        guard let img = NSImage(pasteboard: pb), let tiff = img.tiffRepresentation,
              let rep = NSBitmapImageRep(data: tiff) else { return nil }
        return rep.representation(using: .png, properties: [:])
    }

    func setFromPhone(text: String) {
        pb.clearContents()
        pb.setString(text, forType: .string)
        lastCount = pb.changeCount
    }

    func setFromPhone(imageAt url: URL) {
        guard let img = NSImage(contentsOf: url) else { return }
        pb.clearContents()
        pb.writeObjects([img])
        lastCount = pb.changeCount
    }
}
